export type DenyReason =
  | "THROUGHPUT_SLA_HARD_DENY"
  | "CAPACITY"
  | "HEALTH"
  | "AUTH"
  | "REGION"
  | "POLICY"
  | "OTHER";

export interface EndpointCandidate {
  id: string;
  allowListed: boolean;
}

export interface EndpointEvaluation {
  endpointId: string;
  hardDenied: boolean;
  denyReasons: DenyReason[];
}

export function allowSoleCandidateFallbackOnThroughputSlaOnly(
  candidates: ReadonlyArray<EndpointCandidate>,
  evaluations: ReadonlyArray<EndpointEvaluation>
): string | null {
  const allowListed = candidates.filter((c) => c.allowListed);
  if (allowListed.length !== 1) return null;

  const sole = allowListed[0];
  const evaluation = evaluations.find((e) => e.endpointId === sole.id);
  if (!evaluation || !evaluation.hardDenied) return null;
  if (evaluation.denyReasons.length === 0) return null;

  const throughputOnly = evaluation.denyReasons.every(
    (reason) => reason === "THROUGHPUT_SLA_HARD_DENY"
  );

  return throughputOnly ? sole.id : null;
}
